before:
Complete local Go example; the app itself does not execute it:
```go
package main
import ("fmt"; "errors")
func minutes(n int) (int, error) {
 if n < 0 { return 0, errors.New("negative minutes") }
 return n, nil
}
func main() {
 n, err := minutes(5)
 if err != nil { fmt.Println(err); return }
 fmt.Println(n)
}
```

